package br.com.tapeteskalke.controller; import br.com.tapeteskalke.dto.*; import br.com.tapeteskalke.dto.PermissionDtos.UpdateRequest; import br.com.tapeteskalke.service.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/configuracoes") public class ConfiguracaoController { private final PermissionService permissions; private final PermissionAdminService admin; public ConfiguracaoController(PermissionService permissions,PermissionAdminService admin){this.permissions=permissions;this.admin=admin;} @GetMapping public ApiResponse<?> get(){permissions.page("configuracoes");return ApiResponse.ok(java.util.Map.of("theme","light","pages",permissions.pages(),"actions",permissions.actions()));} @GetMapping("/permissoes") public ApiResponse<?> permissions(){return ApiResponse.ok(java.util.Map.of("pages",permissions.pages(),"actions",permissions.actions()));} @GetMapping("/permissoes/todas") public ApiResponse<?> matrix(){return ApiResponse.ok(admin.matrix());} @PutMapping("/permissoes") public ApiResponse<?> update(@RequestBody UpdateRequest r){admin.update(r);return ApiResponse.ok(java.util.Map.of("updated",true));} }